1	/**
2	 * Regression test: reader settings (fontSize, lineHeight, fontFamily, maxWidth)
3	 * survive an in-place chapter change.
4	 *
5	 * The reader applies these as inline styles on #chapter-text and
6	 * #reader-content via the ReaderStylesHook. Phoenix LiveView's morphdom
7	 * strips JS-set attributes that aren't in the server-rendered template
8	 * when it patches the DOM — so when push_patch swaps the chapter, the
9	 * inline styles get wiped. The fix re-applies settings in the hook's
10	 * `updated` lifecycle. This test pins that behavior.
11	 *
12	 * Skipped automatically when the book has only one chapter (no way to
13	 * trigger a chapter swap via push_patch).
14	 */
15	import { describe, it, before, after } from "node:test";
16	import assert from "node:assert";
17	import { setup, teardown, openReader, sleep } from "../helpers.js";
18	
19	describe("Reader styles persist across chapter swap", () => {
20		let browser, page;
21		let canSwapChapter = false;
22	
23		before(async () => {
24			({ browser, page } = await setup());
25			await openReader(page);
26			await page.waitForSelector("#chapter-text", { timeout: 5000 });
27	
28			const chapterCount = await page.evaluate(() => {
29				const bar = document.getElementById("chapter-bar");
30				return bar ? JSON.parse(bar.dataset.chapters).length : 0;
31			});
32			canSwapChapter = chapterCount >= 2;
33		});
34	
35		after(async () => {
36			await teardown(browser);
37		});
38	
39		it("font size on #chapter-text survives next_chapter push_patch", async (t) => {
40			if (!canSwapChapter) {
41				t.skip("Book has fewer than 2 chapters — cannot exercise swap");
42				return;
43			}
44	
45			// Pick a font size that's clearly different from the default (18).
46			const TARGET_FONT_SIZE = 26;
47	
48			// Seed the persisted settings store and force the hook to apply them.
49			// We poke the store via localStorage and dispatch a storage-style
50			// trigger by re-opening the page so the hook reads the new value
51			// on mount. (Going through the slider would also work, but this is
52			// faster and doesn't depend on the slider's exact min/max range.)
53			await page.evaluate((size) => {
54				const raw = localStorage.getItem("readaloud-reader-settings");
55				const cur = raw ? JSON.parse(raw) : {};
56				cur.fontSize = size;
57				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
58			}, TARGET_FONT_SIZE);
59	
60			await openReader(page);
61			await page.waitForSelector("#chapter-text", { timeout: 5000 });
62	
63			const initialFontSize = await page.$eval("#chapter-text", (el) =>
64				el.style.fontSize,
65			);
66			assert.strictEqual(
67				initialFontSize,
68				`${TARGET_FONT_SIZE}px`,
69				"sanity: hook applied seeded fontSize on initial mount",
70			);
71	
72			const startingChapterId = await page.evaluate(() =>
73				window.location.pathname.match(/\/read\/(\d+)/)?.[1],
74			);
75	
76			// Click the "next chapter" button on the floating pill. This fires
77			// a phx-click="next_chapter" → push_patch on the server, which
78			// patches the DOM in place (no full page navigation).
79			await page.mouse.move(640, 400);
80			await page.mouse.move(641, 401);
81			await page.waitForSelector("#floating-pill.opacity-100", {
82				timeout: 5000,
83			});
84			await page.click('[phx-click="next_chapter"]:not([disabled])');
85	
86			// Wait for the URL to change (push_patch updates window.location).
87			await page.waitForFunction(
88				(prev) => {
89					const m = window.location.pathname.match(/\/read\/(\d+)/);
90					return m && m[1] !== prev;
91				},
92				{ timeout: 5000 },
93				startingChapterId,
94			);
95	
96			// Give morphdom a moment to settle and the hook's updated() to fire.
97			await sleep(200);
98	
99			const fontSizeAfterSwap = await page.$eval("#chapter-text", (el) =>
100				el.style.fontSize,
101			);
102			assert.strictEqual(
103				fontSizeAfterSwap,
104				`${TARGET_FONT_SIZE}px`,
105				"fontSize must survive push_patch chapter swap — without re-apply " +
106					"in the hook's updated() lifecycle, morphdom strips the inline " +
107					"style and the article reverts to the prose-lg default size",
108			);
109		});
110	
111		it("font family and line height also survive the swap", async (t) => {
112			if (!canSwapChapter) {
113				t.skip("Book has fewer than 2 chapters");
114				return;
115			}
116	
117			// We're already on chapter N+1 from the previous test. Set a fresh
118			// non-default fontFamily + lineHeight, reload, then swap chapters.
119			await page.evaluate(() => {
120				const raw = localStorage.getItem("readaloud-reader-settings");
121				const cur = raw ? JSON.parse(raw) : {};
122				cur.fontFamily = "mono";
123				cur.lineHeight = 2.4;
124				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
125			});
126	
127			await openReader(page);
128			await page.waitForSelector("#chapter-text", { timeout: 5000 });
129	
130			const before = await page.$eval("#chapter-text", (el) => ({
131				fontFamily: el.style.fontFamily,
132				lineHeight: el.style.lineHeight,
133			}));
134			assert.match(before.fontFamily, /monospace/i, "sanity: mono applied");
135			assert.strictEqual(before.lineHeight, "2.4", "sanity: lineHeight applied");
136	
137			const startingChapterId = await page.evaluate(() =>
138				window.location.pathname.match(/\/read\/(\d+)/)?.[1],
139			);
140	
141			await page.mouse.move(640, 400);
142			await page.mouse.move(641, 401);
143			await page.waitForSelector("#floating-pill.opacity-100", {
144				timeout: 5000,
145			});
146	
147			// next_chapter may be disabled if we landed on the last chapter;
148			// fall back to prev_chapter in that case.
149			const nextDisabled = await page.$eval(
150				'[phx-click="next_chapter"]',
151				(el) => el.disabled,
152			);
153			const selector = nextDisabled
154				? '[phx-click="prev_chapter"]:not([disabled])'
155				: '[phx-click="next_chapter"]:not([disabled])';
156			await page.click(selector);
157	
158			await page.waitForFunction(
159				(prev) => {
160					const m = window.location.pathname.match(/\/read\/(\d+)/);
161					return m && m[1] !== prev;
162				},
163				{ timeout: 5000 },
164				startingChapterId,
165			);
166			await sleep(200);
167	
168			const after = await page.$eval("#chapter-text", (el) => ({
169				fontFamily: el.style.fontFamily,
170				lineHeight: el.style.lineHeight,
171			}));
172			assert.match(
173				after.fontFamily,
174				/monospace/i,
175				"fontFamily must survive chapter swap",
176			);
177			assert.strictEqual(
178				after.lineHeight,
179				"2.4",
180				"lineHeight must survive chapter swap",
181			);
182		});
183	});
184

