1	/**
2	 * Audio auto-next-chapter test.
3	 *
4	 * Verifies the chapter swap on `ended` keeps the same <audio> element and
5	 * uses LiveView push_patch (no full navigation). This is the critical
6	 * mobile-lock-screen fix: a full navigation tears down the OS audio
7	 * session, which is why autoplay used to fail when the phone was asleep.
8	 *
9	 * Skipped automatically if the test book has no audio-ready chapter
10	 * (e.g. the NixOS VM smoke environment, which seeds chapters without
11	 * generated audio).
12	 */
13	import { describe, it, before, after } from "node:test";
14	import assert from "node:assert";
15	import { setup, teardown, openReader, sleep, BASE_URL } from "../helpers.js";
16	
17	describe("Audio auto-next-chapter", () => {
18		let browser, page;
19		let playerExists = false;
20	
21		before(async () => {
22			({ browser, page } = await setup());
23	
24			// Find a chapter that actually has audio. We don't know the exact id,
25			// so walk chapters from the book and stop at the first one whose
26			// reader page renders the #audio-player element.
27			await openReader(page);
28			const chapters = await page.evaluate(() => {
29				const bar = document.getElementById("chapter-bar");
30				return bar ? JSON.parse(bar.dataset.chapters) : [];
31			});
32	
33			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
34			if (!bookId || chapters.length === 0) return;
35	
36			for (const ch of chapters) {
37				await page.goto(
38					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
39					{ waitUntil: "networkidle2" },
40				);
41				await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
42				await sleep(300);
43				const player = await page.$("#audio-player");
44				if (player) {
45					const nextUrl = await page.$eval(
46						"#audio-player",
47						(el) => el.dataset.nextAudioUrl || "",
48					);
49					if (nextUrl) {
50						playerExists = true;
51						break;
52					}
53				}
54			}
55		});
56	
57		after(async () => {
58			await teardown(browser);
59		});
60	
61		it("player exposes next-chapter data attrs", async (t) => {
62			if (!playerExists) {
63				t.skip("No audio-ready chapter with a next chapter — skipping");
64				return;
65			}
66			const attrs = await page.$eval("#audio-player", (el) => ({
67				audioUrl: el.dataset.audioUrl,
68				nextAudioUrl: el.dataset.nextAudioUrl,
69				nextTimingsUrl: el.dataset.nextTimingsUrl,
70				nextChapterId: el.dataset.nextChapterId,
71				chapterId: el.dataset.chapterId,
72				bookTitle: el.dataset.bookTitle,
73				chapterTitle: el.dataset.chapterTitle,
74			}));
75			assert.ok(attrs.audioUrl, "audioUrl must be set");
76			assert.ok(attrs.nextAudioUrl, "nextAudioUrl must be set");
77			assert.ok(attrs.nextTimingsUrl, "nextTimingsUrl must be set");
78			assert.ok(attrs.nextChapterId, "nextChapterId must be set");
79			assert.notStrictEqual(
80				attrs.audioUrl,
81				attrs.nextAudioUrl,
82				"next URL must differ from current",
83			);
84			assert.ok(attrs.bookTitle, "bookTitle must be set for Media Session");
85			assert.ok(attrs.chapterTitle, "chapterTitle must be set for Media Session");
86		});
87	
88		it("Media Session metadata is registered", async (t) => {
89			if (!playerExists) {
90				t.skip("No audio-ready chapter — skipping");
91				return;
92			}
93			// Wait a tick for the hook to mount and call new MediaMetadata().
94			await sleep(200);
95			const meta = await page.evaluate(() => {
96				if (!("mediaSession" in navigator)) return null;
97				const m = navigator.mediaSession.metadata;
98				if (!m) return null;
99				return { title: m.title, artist: m.artist, album: m.album };
100			});
101			// Headless Chromium supports MediaSession; if it doesn't on a given
102			// runtime, treat as a soft skip rather than a hard failure.
103			if (meta === null) {
104				t.skip("MediaSession not available in this browser");
105				return;
106			}
107			assert.ok(meta.title?.length > 0, "Media Session title should be set");
108			assert.ok(meta.artist?.length > 0, "Media Session artist should be set");
109		});
110	
111		it("prefetches next chapter audio into a Blob URL while current plays", async (t) => {
112			if (!playerExists) {
113				t.skip("No audio-ready chapter — skipping");
114				return;
115			}
116	
117			// Enable autoNextChapter (gates prefetch) and reload so the
118			// PersistedRecord cache picks it up.
119			await page.evaluate(() => {
120				const cur = (() => {
121					try {
122						return JSON.parse(
123							localStorage.getItem("readaloud-reader-settings") || "{}",
124						);
125					} catch {
126						return {};
127					}
128				})();
129				cur.autoNextChapter = true;
130				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
131			});
132			await page.reload({ waitUntil: "networkidle2" });
133			await page.waitForSelector("#audio-element", { timeout: 10000 });
134	
135			// Drive currentTime past the 15% prefetch trigger fraction by
136			// poking the audio element directly. We're not asserting playback,
137			// just want a `timeupdate` to fire with currentTime/duration > 0.15.
138			// Wait for metadata first so duration is known.
139			await page.evaluate(
140				() =>
141					new Promise((resolve) => {
142						const a = document.getElementById("audio-element");
143						if (!a) return resolve();
144						if (a.readyState >= 1 && Number.isFinite(a.duration))
145							return resolve();
146						a.addEventListener("loadedmetadata", () => resolve(), { once: true });
147					}),
148			);
149			await page.evaluate(() => {
150				const a = document.getElementById("audio-element");
151				if (!a || !Number.isFinite(a.duration)) return;
152				a.currentTime = a.duration * 0.2;
153				a.dispatchEvent(new Event("timeupdate"));
154			});
155	
156			// Wait for the fetch + blob URL to materialize. WAV files can be
157			// large; give it some time on a slow machine.
158			const nextUrl = await page.$eval(
159				"#audio-player",
160				(el) => el.dataset.nextAudioUrl || "",
161			);
162			const start = Date.now();
163			let prefetched = false;
164			while (Date.now() - start < 20000) {
165				const found = await page.evaluate(() => {
166					// Look at performance entries — fetch() shows up as a
167					// resource entry. We can't reach into the hook's closure,
168					// but we *can* see if a request to the next-chapter audio
169					// URL has been issued.
170					return performance
171						.getEntriesByType("resource")
172						.some(
173							(e) =>
174								e.name.includes("/api/books/") &&
175								e.name.includes("/audio") &&
176								e.initiatorType === "fetch",
177						);
178				});
179				if (found) {
180					prefetched = true;
181					break;
182				}
183				await sleep(500);
184			}
185			assert.ok(
186				prefetched,
187				`expected a fetch() to ${nextUrl} after currentTime crossed 15%, but none was observed`,
188			);
189		});
190	
191		it("ended event swaps audio.src + patches URL without tearing down player", async (t) => {
192			if (!playerExists) {
193				t.skip("No audio-ready chapter — skipping");
194				return;
195			}
196	
197			// Snapshot current state.
198			const before = await page.evaluate(() => {
199				const player = document.getElementById("audio-player");
200				const audio = document.getElementById("audio-element");
201				return {
202					url: window.location.pathname + window.location.search,
203					audioSrc: audio?.src ?? null,
204					nextAudioUrl: player?.dataset.nextAudioUrl ?? null,
205					nextChapterId: player?.dataset.nextChapterId ?? null,
206					audioNodeId: audio ? audio.dataset.testId : null,
207				};
208			});
209	
210			assert.ok(before.nextAudioUrl, "must have a next audio URL to swap to");
211			assert.ok(
212				before.audioSrc?.includes(
213					`/chapters/${before.url.match(/\/read\/(\d+)/)?.[1]}/audio`,
214				),
215				`audio src should be the current chapter's URL, got ${before.audioSrc}`,
216			);
217	
218			// Auto-next-chapter is a user-controlled reader setting persisted in
219			// localStorage. The hook reads it via PersistedRecord, which caches
220			// the value at module-load time — so we must set localStorage *and
221			// reload* for the new value to be picked up.
222			await page.evaluate(() => {
223				const cur = (() => {
224					try {
225						return JSON.parse(
226							localStorage.getItem("readaloud-reader-settings") || "{}",
227						);
228					} catch {
229						return {};
230					}
231				})();
232				cur.autoNextChapter = true;
233				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
234			});
235			await page.reload({ waitUntil: "networkidle2" });
236			await page.waitForSelector("#audio-element", { timeout: 10000 });
237			await sleep(300);
238	
239			// Mark the (post-reload) audio element so we can prove identity
240			// after the swap. Use a JS expando property (not a DOM attribute)
241			// because morphdom strips attributes not declared in the server
242			// template — even on phx-update="ignore" elements (it preserves
243			// children, not custom attrs).
244			await page.evaluate(() => {
245				const a = document.getElementById("audio-element");
246				if (a) a.__readaloudTestMarker = "same-node-marker";
247			});
248	
249			// Trigger the `ended` event on the audio element. The hook listens
250			// for this and is supposed to swap src to the next chapter and push
251			// next_chapter to the server (push_patch).
252			await page.evaluate(() => {
253				const a = document.getElementById("audio-element");
254				if (a) a.dispatchEvent(new Event("ended"));
255			});
256	
257			// Wait for the JS swap + LV push_patch round-trip.
258			await sleep(2000);
259	
260			const after = await page.evaluate(() => {
261				const audio = document.getElementById("audio-element");
262				return {
263					url: window.location.pathname + window.location.search,
264					audioSrc: audio?.src ?? null,
265					audioNodeMarker: audio ? audio.__readaloudTestMarker : null,
266				};
267			});
268	
269			// Same DOM node — proves push_patch (not push_navigate).
270			assert.strictEqual(
271				after.audioNodeMarker,
272				"same-node-marker",
273				"audio element must be the SAME node — push_navigate would replace it",
274			);
275	
276			// audio.src now points at the next chapter — either as the network
