1	/**
2	 * Audio player re-mount idempotency tests.
3	 *
4	 * Regression tests for the sleeping-mobile-wake bug: when the LiveView
5	 * WebSocket times out during a long phone sleep, the server-side LV
6	 * process is GC'd. On wake the client does a fresh mount with a new LV
7	 * process, which fires `destroyed` then `mounted` on every hook —
8	 * including the audio player.
9	 *
10	 * The <audio> element survives this cycle thanks to phx-update="ignore".
11	 * If the hook re-runs `audio.src = ...; audio.load()` on every mount,
12	 * it stomps the prefetched blob URL the user is currently listening to,
13	 * triggers a refetch from a still-suspended network, and strands the
14	 * user at 00:00/00:00 with a dead play button.
15	 *
16	 * The fix makes mount idempotent: skip the src reset if the audio
17	 * element already has a meaningful src. These tests pin that behavior.
18	 *
19	 * Skipped automatically when no audio-ready chapter exists (NixOS VM
20	 * smoke environment).
21	 */
22	import { describe, it, before, after } from "node:test";
23	import assert from "node:assert";
24	import { setup, teardown, openReader, sleep, BASE_URL } from "../helpers.js";
25	
26	describe("Audio player re-mount idempotency", () => {
27		let browser, page;
28		let playerExists = false;
29	
30		before(async () => {
31			({ browser, page } = await setup());
32	
33			await openReader(page);
34			const chapters = await page.evaluate(() => {
35				const bar = document.getElementById("chapter-bar");
36				return bar ? JSON.parse(bar.dataset.chapters) : [];
37			});
38			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
39			if (!bookId || chapters.length === 0) return;
40	
41			for (const ch of chapters) {
42				await page.goto(
43					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
44					{ waitUntil: "networkidle2" },
45				);
46				await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
47				await sleep(300);
48				if (await page.$("#audio-player")) {
49					playerExists = true;
50					break;
51				}
52			}
53		});
54	
55		after(async () => {
56			await teardown(browser);
57		});
58	
59		it("audio.src is preserved when the hook is destroyed and re-mounted", async (t) => {
60			if (!playerExists) {
61				t.skip("No audio-ready chapter — skipping");
62				return;
63			}
64	
65			// Wait for the initial mount to actually set audio.src.
66			await page.waitForFunction(
67				() => {
68					const a = document.getElementById("audio-element");
69					return a && a.src && a.src.includes("/api/books/");
70				},
71				{ timeout: 5000 },
72			);
73	
74			// Replace the live audio src with a sentinel value. This stands in
75			// for "user is mid-playback on a prefetched blob URL when the LV
76			// times out" — what matters for the bug is that the src is some
77			// non-empty value that the *server* did not put there.
78			const sentinelSrc = `blob:${BASE_URL}/sentinel-${Date.now()}`;
79			await page.evaluate((src) => {
80				const a = document.getElementById("audio-element");
81				a.src = src;
82			}, sentinelSrc);
83	
84			const beforeSrc = await page.$eval("#audio-element", (el) => el.src);
85			assert.strictEqual(beforeSrc, sentinelSrc, "sanity: sentinel applied");
86	
87			// Detach and re-attach the player div. Phoenix LV's MutationObserver
88			// detects this and runs `destroyed` on removal followed by `mounted`
89			// on insertion — the same lifecycle the bug triggers on a real
90			// post-sleep reconnect with a dead server-side LV process.
91			await page.evaluate(() => {
92				const el = document.getElementById("audio-player");
93				window.__remountSaved = {
94					el,
95					parent: el.parentNode,
96					nextSibling: el.nextSibling,
97				};
98				el.remove();
99			});
100	
101			// Give the destroyed callback (and any internal LV bookkeeping) a
102			// tick to run before re-attaching. Without this, the destroy and
103			// mount can collapse into a single MutationObserver flush and
104			// short-circuit the lifecycle we're trying to exercise.
105			await sleep(100);
106	
107			await page.evaluate(() => {
108				const { el, parent, nextSibling } = window.__remountSaved;
109				parent.insertBefore(el, nextSibling);
110				delete window.__remountSaved;
111			});
112	
113			await sleep(500); // mount + any async setup
114	
115			const afterSrc = await page.$eval("#audio-element", (el) => el.src);
116			assert.strictEqual(
117				afterSrc,
118				sentinelSrc,
119				"audio.src must survive a hook destroy/mount cycle — without " +
120					"this, sleeping-mobile autoplay re-stalls on wake when LV " +
121					"reconnects with a fresh process",
122			);
123		});
124	
125		it("audio.currentTime is preserved across destroy/mount (proves load() was not called)", async (t) => {
126			if (!playerExists) {
127				t.skip("No audio-ready chapter — skipping");
128				return;
129			}
130	
131			// Restore real audio src (previous test left a sentinel) and wait
132			// for metadata so we have a valid duration to seek into.
133			await page.evaluate(() => {
134				const a = document.getElementById("audio-element");
135				const player = document.getElementById("audio-player");
136				a.src = player.dataset.audioUrl;
137				a.load();
138			});
139			await page.waitForFunction(
140				() => {
141					const a = document.getElementById("audio-element");
142					return a && Number.isFinite(a.duration) && a.duration > 0;
143				},
144				{ timeout: 10000 },
145			);
146	
147			// Seek to a distinctive non-zero time. The OLD code's destroy →
148			// mount cycle called `audio.src = url; audio.load()` on mount,
149			// and load() resets currentTime to 0. The NEW code skips that
150			// when src is already set, so currentTime survives.
151			const SEEK_SECONDS = 7.5;
152			await page.evaluate((t) => {
153				const a = document.getElementById("audio-element");
154				a.currentTime = t;
155			}, SEEK_SECONDS);
156			await sleep(50);
157	
158			const beforeTime = await page.$eval(
159				"#audio-element",
160				(el) => el.currentTime,
161			);
162			assert.ok(
163				Math.abs(beforeTime - SEEK_SECONDS) < 1,
164				`sanity: currentTime should be near ${SEEK_SECONDS}, got ${beforeTime}`,
165			);
166	
167			// Re-mount cycle.
168			await page.evaluate(() => {
169				const el = document.getElementById("audio-player");
170				window.__remountSaved = {
171					el,
172					parent: el.parentNode,
173					nextSibling: el.nextSibling,
174				};
175				el.remove();
176			});
177			await sleep(100);
178			await page.evaluate(() => {
179				const { el, parent, nextSibling } = window.__remountSaved;
180				parent.insertBefore(el, nextSibling);
181				delete window.__remountSaved;
182			});
183			await sleep(500);
184	
185			const afterTime = await page.$eval(
186				"#audio-element",
187				(el) => el.currentTime,
188			);
189			// audio.load() resets currentTime to 0; if the hook called it on
190			// mount (the regression), this drops to ~0. Allow a small window
191			// for natural drift if the audio happened to be playing.
192			assert.ok(
193				Math.abs(afterTime - SEEK_SECONDS) < 1.5,
194				`currentTime should survive re-mount (was ${beforeTime}, now ${afterTime}). ` +
195					`If this drops to ~0, the hook is calling audio.load() on re-mount, ` +
196					`which is the sleeping-mobile-wake regression.`,
197			);
198		});
199	
200		it("the mount-time idempotency heuristic accepts blob: and network URLs", async () => {
201			// This is a documentation-of-contract test. The hook decides
202			// "should I reset audio.src on mount?" based on whether the
203			// existing src is meaningful. If you change the heuristic in
204			// audio_player.ts, update this test too — and think hard about
205			// whether the change breaks the sleeping-mobile-wake invariant.
206			const verdicts = await page.evaluate(() => {
207				const a = document.createElement("audio");
208				const samples = [
209					"",
210					window.location.href,
211					`${window.location.origin}/`,
212					"http://example.com/audio.wav",
213					"blob:http://localhost/abc-123",
214					`${window.location.origin}/api/books/2/chapters/3/audio`,
215				];
216				return samples.map((src) => {
217					a.src = src;
218					const real = a.src;
219					const meaningful =
220						real !== "" &&
221						real !== window.location.href &&
222						real !== `${window.location.origin}/`;
223					return { setSrc: src, realSrc: real, meaningful };
224				});
225			});
226	
227			// Empty / page-URL fallbacks → not meaningful, mount should reset.
228			assert.strictEqual(verdicts[0].meaningful, false, "empty src");
229			assert.strictEqual(verdicts[1].meaningful, false, "page URL src");
230			assert.strictEqual(verdicts[2].meaningful, false, "origin/ src");
231			// Real URLs → meaningful, mount should leave alone.
232			assert.strictEqual(verdicts[3].meaningful, true, "external URL");
233			assert.strictEqual(verdicts[4].meaningful, true, "blob: URL");
234			assert.strictEqual(verdicts[5].meaningful, true, "same-origin api URL");
235		});
236	});
