				swatches.length > 10,
				`Should have many theme swatches, got ${swatches.length}`,
			);
		});

		it("dark and light groups both exist", async () => {
			const darkLabel = await page.$eval("#reader-settings", (el) =>
				el.textContent.includes("Dark"),
			);
			const lightLabel = await page.$eval("#reader-settings", (el) =>
				el.textContent.includes("Light"),
			);
			assert.ok(darkLabel, "Should have Dark themes group");
			assert.ok(lightLabel, "Should have Light themes group");
