		const urlBefore = page.url();

		// Click the "Stay" button (btn-ghost)
		await page.click(".modal-action .btn-ghost");
		await page.waitForFunction(
			() => document.querySelector(".modal.modal-open") === null,
			{ timeout: 3000 },
		);

